app.get('/api/health', (req, res) => res.json({ ok: true, storage: pool ? 'database' : 'files', users: read(F.users).length, dbCreatedAt: meta.createdAt }));

// ---------- Онлайн ----------
const sockets = new Map(); // userId -> Set<ws>

// Галочка у аккаунтов с этими юзернеймами. Свой список: VERIFIED_HANDLES=saimon,durov,lesha
const VERIFIED = new Set((process.env.VERIFIED_HANDLES || 'saimon,admin,lesha,anna')
    .split(',').map(x => x.trim().replace(/^@/, '').toLowerCase()).filter(Boolean));

// Бесконечные Mars. Свой список: UNLIMITED_MARS_HANDLES=saimon,другой
const UNLIMITED = new Set((process.env.UNLIMITED_MARS_HANDLES || 'saimon')
    .split(',').map(x => x.trim().replace(/^@/, '').toLowerCase()).filter(Boolean));
const isUnlimited = u => UNLIMITED.has(u.handle);
const walletOf = u => ({ mars: u.mars || 0, unlimited: isUnlimited(u) });

// ===== Приватность =====
// «Контакты» — те, с кем вы сами переписывались в личке, или кого вы сохранили под своим именем
let _sentCache = { raw: null, set: null };
function sentSet() {
    const raw = mem[keyOf(F.messages)];
    if (_sentCache.raw === raw) return _sentCache.set;
    const set = new Set();
    try { for (const m of JSON.parse(raw)) if (typeof m.chatId === 'string' && m.chatId.startsWith('d_') && !m.call) set.add(m.chatId + ':' + m.senderId); } catch {}
    _sentCache = { raw, set };
    return set;
}
const isContact = (owner, otherId) => !!otherId && (!!(owner.contactNames && owner.contactNames[otherId]) || (Array.isArray(owner.contacts) && owner.contacts.includes(Number(otherId))) || sentSet().has(directId(owner.id, otherId) + ':' + owner.id));
const PRIV_MODES = ['everybody', 'contacts', 'nobody'];
function privOk(owner, field, viewer) {
    const mode = owner[field] || 'everybody';
    if (mode === 'everybody' || viewer === owner.id) return true;
    if (mode === 'nobody' || !viewer) return false;
    return isContact(owner, viewer);
}
const viewerId = () => { const s = viewerCtx.getStore(); return s ? s.uid : null; };

const pub = u => ({
    id: u.id, username: u.username, handle: u.handle, verified: VERIFIED.has(u.handle) || !!u.verified, bio: u.bio || '',
    // Полный список юзернеймов отдаём всегда (не только когда их больше одного) — иначе клиент при
    // каждом обновлении профиля (checkSession при заходе в приложение) может «забыть» второстепенные
    // юзернеймы, если локальный кэш в браузере когда-то сохранился без них, и их станет не продать.
    handles: u.handles && u.handles.length ? u.handles : [u.handle],
    ...((u.handles || [u.handle]).length > 1 ? { others: u.handles.filter(h => h !== u.handle) } : {}),
    avatar: privOk(u, 'privPhoto', viewerId()) ? (u.avatar || '') : '', createdAt: u.createdAt, ...(u.handleBuys && Object.keys(u.handleBuys).length ? { buys: u.handleBuys } : {}), online: sockets.has(u.id), ...(!sockets.has(u.id) && u.lastSeen && u.lastSeenMode !== 'nobody' ? { lastSeen: u.lastSeen } : {}), ...(u.bot && { bot: true }), ...(u.custom && { custom: true, ownerId: u.ownerId, ...(u.botApp && { app: u.botApp }) }), ...(u.acc && { acc: u.acc }), ...(u.banned && { banned: true }), ...(u.rainbowBorder && premiumOn(u) && { rainbowBorder: true }), ...(u.rbColors && u.rainbowBorder ? { rbColors: u.rbColors } : {}), ...(u.pinnedNft && { pinnedNft: u.pinnedNft }), ...(u.pinnedChannel && { pinnedChannel: u.pinnedChannel, pinnedChannelData: (() => { const _ch = read(F.chats).find(c => c.id === u.pinnedChannel && c.type === 'channel'); return _ch ? { id: _ch.id, name: _ch.name, handle: _ch.handle || '', avatar: _ch.avatar || '', subscribers: _ch.members ? _ch.members.length : 0 } : null; })() }), ...(premiumOn(u) && { premium: u.premium, ...(u.nickGrad && { ng: u.nickGrad }) })
});
const self = u => ({ ...pub(u), avatar: u.avatar || '', email: u.email, ...walletOf(u), lastSeenMode: u.lastSeenMode || 'everybody', lastSeen: u.lastSeen || null,
    archived: u.archived || [],
    privCall: u.privCall || 'everybody', privPhoto: u.privPhoto || 'everybody', privGift: u.privGift || 'everybody', readReceipts: u.readReceipts !== false, pushPreview: u.pushPreview !== false,
    ...(u.uListings && u.uListings.length ? { uListings: u.uListings, uListing: u.uListings.find(l => l.handle === u.handle) } : {}),
    ...(u.handles && u.handles.length > 1 ? { handles: u.handles } : {}),
    ...(u.pinnedChannel ? { pinnedChannel: u.pinnedChannel } : {}), ...(u.rbColors ? { rbColors: u.rbColors } : {}),
    ...(u.pinnedNft ? { pinnedNft: u.pinnedNft } : {}) });

function sendTo(ids, payload, exceptWs) {
    const json = JSON.stringify(payload);
    ids.forEach(id => sockets.get(id)?.forEach(s => {
        if (s !== exceptWs && s.readyState === WebSocket.OPEN) s.send(json);
    }));
}
function broadcast(payload) {
    const json = JSON.stringify(payload);
    wss.clients.forEach(s => s.readyState === WebSocket.OPEN && s.send(json));
}

// Чат в виде, удобном клиенту. list — сообщения этого чата
// Реакции и просмотры постов канала
const REACTIONS = ['👍', '❤️', '🔥', '😂', '😮', '😢', '🎉', '👎'];
// Индекс пользователей: read() каждый раз парсит файл целиком, поэтому строим его лениво и один раз на запрос
const lazyIdx = () => { let mp; return () => mp || (mp = new Map(read(F.users).map(u => [u.id, u]))); };
const ixCache = new WeakMap();
const ixOf = arr => { let m = ixCache.get(arr); if (!m) { m = new Map(arr.map(u => [u.id, u])); ixCache.set(arr, m); } return m; };
const userLite = u => ({ id: u.id, username: u.username, avatar: u.avatar || '', verified: VERIFIED.has(u.handle), ...(u.acc && { acc: u.acc }) });
// Наружу отдаём сообщение без служебных полей.
// Лента канала: просмотры (настоящие + «накрученные» подписчики, которые просматривают пост постепенно) и комментарии.
// Текстовый канал (open): как группа — у сообщения есть имя отправителя.
function outMsg(m, chat, ix = lazyIdx()) {
    if (!m || !chat || chat.type !== 'channel') return m;
    const { viewers, fv, comments, ...o } = m;
    if (chat.open) {
        const u = ix().get(m.senderId);
        if (u) { o.sn = u.username; if (VERIFIED.has(u.handle)) o.sv = true; if (u.acc) o.sacc = u.acc; }
        return o;
    }
    const age = Date.now() - new Date(m.timestamp).getTime();
    o.views = (viewers ? viewers.length : 0) + Math.round((fv || 0) * Math.min(1, 0.25 + age / 240000));
    o.cc = comments ? comments.length : 0;
    if (o.cc) {
        const seen = [];
        for (let i = comments.length - 1; i >= 0 && seen.length < 3; i--) if (!seen.includes(comments[i].userId)) seen.push(comments[i].userId);
        o.ca = seen.map(id => ix().get(id)).filter(Boolean).map(u => ({ id: u.id, username: u.username, avatar: u.avatar || '' }));
    }
    return o;
}
const fakeInChannel = (chat, users) => {
    const fk = new Set(users.filter(u => u.fake).map(u => u.id));
    return chat.members.reduce((n, id) => n + (fk.has(id) ? 1 : 0), 0);
};
const rollFv = n => Math.round(n * (0.35 + Math.random() * 0.5));
// Участник открыл канал — все посты получают его просмотр
function markViews(chat, uid) {
    const msgs = read(F.messages);
    let items = null, fakeN = null;
    msgs.forEach(x => {
        if (x.chatId !== chat.id) return;
        let ch = false;
        if (x.fv === undefined) { if (fakeN === null) fakeN = fakeInChannel(chat, read(F.users)); x.fv = rollFv(fakeN); ch = true; }
        x.viewers = x.viewers || [];
        if (!x.viewers.includes(uid)) { x.viewers.push(uid); ch = true; }
        if (ch) (items = items || {})[x.id] = outMsg(x, chat).views;
    });
    if (!items) return;
    write(F.messages, msgs);
    sendTo([...new Set([uid, chat.creator])], { type: 'views', data: { chatId: chat.id, items } });
}

function shape(chat, me, users, list) {
    const clr = (chat.cleared || {})[me] || ''; // «удалил чат у себя»: старые сообщения скрыты
    if (clr) list = list.filter(m => m.timestamp > clr);
    const byId = id => users.find(u => u.id === id);
    const reads = chat.reads || {};
    const rrOff = id => { const x = byId(id); return !!x && x.readReceipts === false; };
    // Отчёты о прочтении: выключивший не показывает свои ✓✓ и сам не видит чужие
    const outReads = rrOff(me) ? (reads[me] ? { [me]: reads[me] } : {}) : Object.fromEntries(Object.entries(reads).filter(([k]) => Number(k) === me || !rrOff(Number(k))));
    const o = {
        id: chat.id, type: chat.type, name: chat.name, avatar: chat.avatar || '',
        creator: chat.creator, createdAt: chat.createdAt, reads: outReads, ttl: chat.ttl || 0,
        last: outMsg(list[list.length - 1] || null, chat, () => ixOf(users)),
        unread: list.filter(m => m.senderId !== me && m.timestamp > (reads[me] || '')).length,
        mentions: list.filter(m => m.mentions && m.mentions.includes(me) && m.timestamp > (reads[me] || '')).length,
        pins: (chat.pins || []).map(id => list.find(m => m.id === id)).filter(Boolean)
            .map(m => ({ id: m.id, senderId: m.senderId,
                name: ((users.find(u => u.id === m.senderId) || {}).username) || '—',
                text: String(m.text || '').slice(0, 90),
                media: m.media ? m.media.kind : (m.gift ? 'gift' : '') }))
    };
    if (chat.type === 'direct') {
        const p = byId(chat.members.find(i => i !== me));
        o.peer = p ? pub(p) : null;
    } else if (chat.type === 'group') {
        o.members = chat.members.map(byId).filter(Boolean).map(pub);
    } else if (chat.type === 'saved') {
        o.name = 'Избранное';
        o.members = chat.members.map(byId).filter(Boolean).map(pub);
    } else { // канал
        o.description = chat.description || '';
        o.handle = chat.handle || '';
        o.open = !!chat.open;
        o.subscribers = chat.members.length;
        o.verified = chat.members.length >= 10000 || !!chat.legacyVerified; // галочка: 10000+ подп. или старый 5000+ (legacyVerified)
        if (chat.creator === me) o.members = chat.members.map(byId).filter(Boolean).map(pub); // список подписчиков видит автор
    }
    return o;
}
const one = (chat, me) => shape(chat, me, read(F.users), read(F.messages).filter(m => m.chatId === chat.id));

// ---------- Загрузка файлов ----------
app.post('/api/upload', express.raw({ type: () => true, limit: '50mb' }), async (req, res) => {
    const uid = Number(req.query.userId);
    if (!read(F.users).some(u => u.id === uid)) return res.status(401).json({ error: 'Войдите в аккаунт' });

    let srcExt = MIME[String(req.headers['content-type'] || '').split(';')[0].trim()];
    if (!srcExt && req.query.ext) {
        // клиент передал расширение исходного файла как ?ext=mp4 — используем как запасной вариант
        const extFallback = String(req.query.ext).toLowerCase().replace(/^\./, '');
        if (Object.values(MIME).includes(extFallback)) srcExt = extFallback;
        else if (['3gp','3gpp','3gpp2','m4v','avi','mkv','hevc','ts'].includes(extFallback)) srcExt = 'mp4';
    }
    if (!srcExt) return res.status(400).json({ error: 'Поддерживаются фото (JPG, PNG, WebP, GIF) и видео (MP4, WebM, MOV)' });

    const buf = req.body;
    if (!Buffer.isBuffer(buf) || !buf.length) return res.status(400).json({ error: 'Пустой файл' });

    const isImg = !['mp4', 'webm', 'mov', 'weba', 'm4a', 'ogg', 'mp3'].includes(srcExt);
    if (req.query.kind === 'avatar' && (!isImg || buf.length > 5 * 1024 * 1024))
        return res.status(400).json({ error: 'Для аватарки нужно фото до 5 МБ' });
    if (req.query.kind === 'voice' && isImg)
        return res.status(400).json({ error: 'Голосовое сообщение — это аудио' });

    let outBuf = buf, ext = srcExt;
    if (!isImg) {
        const isVideo = ['mp4', 'webm', 'mov'].includes(srcExt);
        try {
            outBuf = await transcodeToCompat(buf, srcExt, isVideo);
            ext = isVideo ? 'mp4' : 'm4a';
        } catch (e) {
            // Перекодирование — это бонус для совместимости с iPhone, а не обязательное условие отправки.
            // Если ffmpeg не смог (нет на хостинге, упал, видео экзотического формата) —
            // отправляем файл как есть, а не блокируем сообщение целиком.
            console.error('transcode: не удалось перекодировать, отправляю оригинал —', e.message);
            outBuf = buf;
            ext = srcExt;
        }
    }

    const name = crypto.randomUUID() + '.' + ext;
    try {
        await fs.promises.writeFile(path.join(UP, name), outBuf);
        if (pool) await pool.query('insert into files (name, data) values ($1, $2)', [name, outBuf]);
    } catch (e) {
        console.error('upload:', e.message);
        return res.status(500).json({ error: 'Не удалось сохранить файл' });
    }
    res.json({ url: '/uploads/' + name, kind: isImg ? 'image' : 'video' });
});

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
// Расшифровка голосовых на сервере — если задан ключ Whisper-совместимого API (OpenAI, Groq и т.п.).
// Без ключа расшифровка выполняется прямо в браузере получателя (модель Whisper скачивается один раз).
const STT_KEY = process.env.STT_API_KEY || process.env.OPENAI_API_KEY || '';
const STT_URL = process.env.STT_URL || 'https://api.openai.com/v1/audio/transcriptions';
const STT_MODEL = process.env.STT_MODEL || 'whisper-1';
