// ---------- Оплата в Mars в мини-приложениях ----------
const PAY_MAX = 100000;
app.post('/api/bots/:id/app/pay', async (req, res) => {
    const o = botForApp(req, res); if (!o) return;
    const amount = Math.floor(Number(req.body.amount));
    const title = clean(req.body.title, 80).trim() || 'Оплата';
    const payload = clean(typeof req.body.payload === 'string' ? req.body.payload : JSON.stringify(req.body.payload ?? ''), 500);
    if (!Number.isFinite(amount) || amount < 1 || amount > PAY_MAX) return res.status(400).json({ error: `Сумма — от 1 до ${PAY_MAX} Mars` });
    if (req.uid === o.bot.ownerId) return res.status(400).json({ error: 'Это ваш бот — платить самому себе нельзя. Проверьте оплату в предпросмотре.' });
    if (!rateOk('p' + o.bot.id + ':' + req.uid, 2000)) return res.status(429).json({ error: 'Подождите пару секунд' });
    const users = read(F.users), payer = users.find(u => u.id === req.uid), owner = users.find(u => u.id === o.bot.ownerId);
    if (!payer || !owner) return res.status(400).json({ error: 'Оплата недоступна' });
    if (!isUnlimited(payer) && (payer.mars || 0) < amount) return res.status(400).json({ error: `Не хватает Mars: нужно ${amount}, у вас ${payer.mars || 0}` });
    if (!isUnlimited(payer)) payer.mars = (payer.mars || 0) - amount;
    if (!isUnlimited(owner)) owner.mars = (owner.mars || 0) + amount;
    write(F.users, users);
    const pay = { id: 'p_' + crypto.randomUUID().slice(0, 12), from: payer.id, name: payer.username, handle: payer.handle, amount, title, payload, at: new Date().toISOString() };
    o.cfg.payments = [...(o.cfg.payments || []), pay].slice(-500);
    o.cfg.stats.revenue = (o.cfg.stats.revenue || 0) + amount;
    trackUser(o.cfg, payer.id);
    write(F.bots, o.db);
    sendTo([payer.id], { type: 'wallet', data: walletOf(payer) });
    sendTo([owner.id], { type: 'wallet', data: walletOf(owner) });
    botPost(o.bot.id, payer.id, `🧾 Оплата прошла\n${title}\n\n−${amount} Mars · чек ${pay.id}`);
    hoursSay(owner.id, `💰 +${amount} Mars через @${o.bot.handle}\nот ${payer.username}${payer.handle ? ' (@' + payer.handle + ')' : ''}\n«${title}»${payload ? '\n\nДанные: ' + payload : ''}`, [[hb('↩️ Ответить от имени бота', 'reply', `${o.bot.id}:${payer.id}`)]]);
    await persist();
    res.json({ success: true, id: pay.id, amount, ...walletOf(payer) });
});
// Возврат платежа владельцем
app.post('/api/hours/bots/:id/refund', async (req, res) => {
    const o = ownBot(req, res); if (!o) return;
    const cfg = o.db[o.bot.id], pay = (cfg.payments || []).find(p => p.id === String(req.body.payId));
    if (!pay) return res.status(404).json({ error: 'Платёж не найден' });
    if (pay.refunded) return res.status(400).json({ error: 'Уже возвращён' });
    const owner = o.users.find(u => u.id === req.uid), payer = o.users.find(u => u.id === pay.from);
    if (!payer) return res.status(400).json({ error: 'Покупатель удалил аккаунт' });
    if (!isUnlimited(owner) && (owner.mars || 0) < pay.amount) return res.status(400).json({ error: `Для возврата нужно ${pay.amount} Mars на вашем балансе` });
    if (!isUnlimited(owner)) owner.mars -= pay.amount;
    if (!isUnlimited(payer)) payer.mars = (payer.mars || 0) + pay.amount;
    pay.refunded = new Date().toISOString();
    cfg.stats.revenue = Math.max(0, (cfg.stats.revenue || 0) - pay.amount);
    write(F.users, o.users); write(F.bots, o.db);
    sendTo([payer.id], { type: 'wallet', data: walletOf(payer) });
    sendTo([owner.id], { type: 'wallet', data: walletOf(owner) });
    botPost(o.bot.id, payer.id, `↩️ Возврат: +${pay.amount} Mars\n«${pay.title}» · чек ${pay.id}`);
    await persist();
    res.json({ success: true });
});

// ===================================================================
//  Превью ссылок: сервер сам открывает страницу, берёт заголовок,
//  описание и картинку (og:*). Защита от обращений во внутреннюю сеть.
// ===================================================================
const lpHttps = require('https'), lpDns = require('dns'), lpNet = require('net'), lpZlib = require('zlib');

// Адрес из внутренней/служебной сети — туда сервер ходить не должен (SSRF)
function lpPrivateIp(ip) {
    if (lpNet.isIPv4(ip)) {
        const [a, b] = ip.split('.').map(Number);
        return a === 0 || a === 10 || a === 127 || a >= 224 || (a === 100 && b >= 64 && b <= 127) || (a === 169 && b === 254) ||
            (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 198 && (b === 18 || b === 19)) || (a === 192 && b === 0);
    }
    const s = ip.toLowerCase();
    if (s.startsWith('::ffff:')) return lpPrivateIp(s.slice(7));
    return s === '::' || s === '::1' || s.startsWith('fc') || s.startsWith('fd') || s.startsWith('fe8') || s.startsWith('fe9') || s.startsWith('fea') || s.startsWith('feb');
}
// DNS с проверкой: адрес проверяется в момент соединения (защита от подмены DNS)
function lpLookup(host, opts, cb) {
    lpDns.lookup(host, { all: true }, (err, addrs) => {
        if (err) return cb(err);
        if (!addrs.length || addrs.some(a => lpPrivateIp(a.address))) return cb(Object.assign(new Error('blocked address'), { code: 'EBLOCKED' }));
        if (opts && opts.all) cb(null, addrs); else cb(null, addrs[0].address, addrs[0].family);
    });
}
// Скачать по http(s) с ограничениями: время, размер, редиректы, только стандартные порты
function lpGet(url, { maxBytes = 400000, accept = 'text/html,application/xhtml+xml', redirects = 4, timeout = 6000 } = {}) {
    return new Promise((resolve, reject) => {
        let u;
        try { u = new URL(url); } catch { return reject(new Error('bad url')); }
        if (!/^https?:$/.test(u.protocol) || (u.port && !['80', '443'].includes(u.port)) || u.username || u.password) return reject(new Error('url not allowed'));
        if (lpNet.isIP(u.hostname.replace(/^\[|\]$/g, '')) && lpPrivateIp(u.hostname.replace(/^\[|\]$/g, ''))) return reject(new Error('blocked address'));
        const mod = u.protocol === 'https:' ? lpHttps : http;
        const req = mod.get(u, { lookup: lpLookup, timeout, headers: { 'User-Agent': 'Mozilla/5.0 (compatible; SaimongramBot/1.0; link preview)', Accept: accept, 'Accept-Language': 'ru,en;q=0.8', 'Accept-Encoding': 'gzip, deflate, br' } }, res => {
            if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
                res.resume();
                if (redirects <= 0) return reject(new Error('too many redirects'));
                let next; try { next = new URL(res.headers.location, u).href; } catch { return reject(new Error('bad redirect')); }
                return lpGet(next, { maxBytes, accept, redirects: redirects - 1, timeout }).then(resolve, reject);
            }
            if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode)); }
            const enc = String(res.headers['content-encoding'] || '').toLowerCase();
            let stream = res;
            if (enc === 'gzip') stream = res.pipe(lpZlib.createGunzip());
            else if (enc === 'deflate') stream = res.pipe(lpZlib.createInflate());
            else if (enc === 'br') stream = res.pipe(lpZlib.createBrotliDecompress());
            const chunks = []; let size = 0, done = false;
            const finish = () => { if (done) return; done = true; req.destroy(); resolve({ body: Buffer.concat(chunks), type: String(res.headers['content-type'] || ''), url: u.href }); };
            stream.on('data', c => { if (done) return; chunks.push(c); size += c.length; if (size >= maxBytes) finish(); });
            stream.on('end', finish);
            stream.on('error', e => { if (size) finish(); else if (!done) { done = true; reject(e); } });
        });
        req.on('timeout', () => req.destroy(new Error('timeout')));
        req.on('error', reject);
    });
}
const lpEntities = s => String(s || '').replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp|laquo|raquo|mdash|ndash|hellip);/gi, (m, e) => {
    const k = e.toLowerCase();
    if (k[0] === '#') { const n = k[1] === 'x' ? parseInt(k.slice(2), 16) : parseInt(k.slice(1), 10); try { return String.fromCodePoint(n); } catch { return ''; } }
    return { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»', mdash: '—', ndash: '–', hellip: '…' }[k];
});
const lpTrim = (s, n) => { s = lpEntities(s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s; };
// Разбор <meta> и <title> из начала страницы
function lpParse(html, pageUrl) {
    const head = html.slice(0, 300000);
    const metas = {};
    for (const m of head.matchAll(/<meta\b[^>]*>/gi)) {
        const tag = m[0], attr = n => { const r = tag.match(new RegExp(n + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i')); return r ? (r[2] ?? r[3] ?? r[4] ?? '') : null; };
        const key = (attr('property') || attr('name') || attr('itemprop') || '').toLowerCase(), val = attr('content');
        if (key && val != null && !(key in metas)) metas[key] = val;
    }
    const title = metas['og:title'] || metas['twitter:title'] || ((head.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]) || '';
    const desc = metas['og:description'] || metas['twitter:description'] || metas['description'] || '';
    let img = metas['og:image:secure_url'] || metas['og:image'] || metas['og:image:url'] || metas['twitter:image'] || metas['twitter:image:src'] || '';
    const host = new URL(pageUrl).hostname.replace(/^www\./, '');
    const site = metas['og:site_name'] || host;
    try { img = img ? new URL(lpEntities(img).trim(), pageUrl).href : ''; } catch { img = ''; }
    if (img && !/^https?:\/\//i.test(img)) img = '';
    const w = Number(metas['og:image:width']) || 0, h = Number(metas['og:image:height']) || 0;
    return { site: lpTrim(site, 60), title: lpTrim(title, 140), desc: lpTrim(desc, 260), img, w, h, host };
}
function lpDecode(buf, type) {
    let cs = (type.match(/charset=([\w-]+)/i) || [])[1];
    if (!cs) { const m = buf.slice(0, 4096).toString('latin1').match(/<meta[^>]+charset=["']?([\w-]+)/i); cs = m && m[1]; }
    try { return new TextDecoder((cs || 'utf-8').toLowerCase()).decode(buf); } catch { return buf.toString('utf8'); }
}
// Подпись адреса картинки, чтобы прокси нельзя было использовать для чего угодно
const lpSecret = () => process.env.LP_SECRET || (meta && meta.vapid && meta.vapid.d) || (meta && meta.createdAt) || 'saimongram';
const lpSign = u => crypto.createHmac('sha256', lpSecret()).update(u).digest('hex').slice(0, 24);
const lpImgPath = u => '/lp/img?u=' + encodeURIComponent(u) + '&s=' + lpSign(u);

const lpCache = new Map(); // url → {at, data}
async function linkPreview(url) {
    const hit = lpCache.get(url);
    if (hit && Date.now() - hit.at < 6 * 3600e3) return hit.data;
    let data = null;
    try {
        const r = await lpGet(url);
        if (/^image\//i.test(r.type)) { const host = new URL(r.url).hostname.replace(/^www\./, ''); data = { url, site: host, title: '', desc: '', img: lpImgPath(r.url), big: true }; }
        else if (/html|xml/i.test(r.type) || !r.type) {
            const p = lpParse(lpDecode(r.body, r.type), r.url);
            if (p.title || p.desc || p.img) data = { url, site: p.site, title: p.title, desc: p.desc, ...(p.img && { img: lpImgPath(p.img), big: !p.w || p.w >= 400 && p.w >= (p.h || 0) }) };
        }
    } catch (e) { /* сайт недоступен — просто без превью */ }
    lpCache.set(url, { at: Date.now(), data });
    if (lpCache.size > 1000) lpCache.delete(lpCache.keys().next().value);
    return data;
}
// Первая ссылка в тексте
const LP_URL_RE = /(^|[^@\w.\/])((?:https?:\/\/|www\.)[^\s<>"'«»]+[^\s<>"'«».,;:!?)\]]|(?:[a-z0-9а-яё-]+\.)+(?:ru|com|org|net|io|me|dev|app|su|ua|by|kz|uz|info|xyz|tv|gg|co|site|online|store|shop|pro|рф|ai|tech|art|link|live|top|club|blog|news|edu|gov|eu|de|uk|us)(?![a-zа-яё0-9-])(?:\/[^\s<>"'«»]*[^\s<>"'«».,;:!?)\]])?)/i;
function firstUrl(text) {
    const m = String(text || '').match(LP_URL_RE);
    if (!m) return null;
    const raw = m[2];
    return /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
}
// Прикрепить превью к сообщению (в фоне) и разослать участникам
function attachPreview(msgId) {
    const msg0 = read(F.messages).find(m => m.id === msgId);
    const url = msg0 && !msg0.sys && firstUrl(msg0.text);
    if (!url) return;
    linkPreview(url).then(p => {
        const msgs = read(F.messages), msg = msgs.find(m => m.id === msgId);
        if (!msg || firstUrl(msg.text) !== url) return;
        if (p) msg.preview = p; else delete msg.preview;
        write(F.messages, msgs);
        const chat = read(F.chats).find(c => c.id === msg.chatId);
        if (chat) sendTo(chat.members, { type: 'msgPreview', data: { chatId: msg.chatId, messageId: msg.id, preview: p || null } });
    }).catch(() => {});
}
// Прокси картинок превью (без него браузер собеседника ходил бы на чужой сайт напрямую)
app.get('/lp/img', async (req, res) => {
    const u = String(req.query.u || ''), s = String(req.query.s || '');
    if (!u || s.length !== 24 || !crypto.timingSafeEqual(Buffer.from(s), Buffer.from(lpSign(u)))) return res.sendStatus(403);
    try {
        const r = await lpGet(u, { maxBytes: 3 * 1024 * 1024 + 1, accept: 'image/avif,image/webp,image/png,image/jpeg,image/gif,image/*;q=0.8' });
        if (!/^image\/(png|jpe?g|gif|webp|avif)/i.test(r.type) || r.body.length > 3 * 1024 * 1024) return res.sendStatus(415);
        res.set({ 'Content-Type': r.type.split(';')[0], 'Cache-Control': 'public, max-age=86400', 'X-Content-Type-Options': 'nosniff', 'Content-Security-Policy': "default-src 'none'" });
        res.send(r.body);
    } catch { res.sendStatus(404); }
});

// ---------- Картинки подарков ----------
// 3D-иллюстрации Fluent Emoji (Microsoft, лицензия MIT: https://github.com/microsoft/fluentui-emoji),
// уменьшенные до 256px в WebP. Встроены прямо в сервер, чтобы не нужно было загружать отдельную папку.
const GIFT_IMG_B64 = {
    heart: '',
    star: '',
    flower: '',
    coffee: '',
    pizza: '',
    bear: '',
    cat: '',
    balloon: '',
    rocket: '',
    gamepad: '',
    rose: '',
    cake: '',
    ghost: '',
    diamond: '',
    unicorn: '',
    trophy: '',
    fire: '',
    crown: '',
    moon: '',
    alien: '',
    ufo: '',
    dragon: '',
    planet: '',
    phoenix: '',
    infinity: '',
};
const GIFT_IMG = new Map(Object.entries(GIFT_IMG_B64).map(([k, v]) => [k, Buffer.from(v, 'base64')]));
const GIFT_IMG_TAG = new Map([...GIFT_IMG].map(([k, b]) => [k, '"' + crypto.createHash('sha1').update(b).digest('hex').slice(0, 16) + '"']));
app.get('/gift-img/:file', (req, res) => {
    const m = /^([a-z]+)\.webp$/.exec(String(req.params.file || ''));
    const buf = m && GIFT_IMG.get(m[1]);
    if (!buf) return res.sendStatus(404);
    const tag = GIFT_IMG_TAG.get(m[1]);
    res.set({ 'Content-Type': 'image/webp', 'Cache-Control': 'public, max-age=604800', ETag: tag, 'X-Content-Type-Options': 'nosniff' });
    if (req.headers['if-none-match'] === tag) return res.sendStatus(304);
    res.send(buf);
});

// ---------- Блокировка пользователей ----------
const blocksOf = uid => read(F.blocks)[uid] || [];
const iBlocked = (a, b) => blocksOf(a).includes(b);            // a заблокировал b
const blockedEither = (a, b) => iBlocked(a, b) || iBlocked(b, a);

app.post('/api/block/:userId', (req, res) => {
    const me = req.uid, target = Number(req.params.userId);
    if (me === target) return res.status(400).json({ error: 'Нельзя заблокировать самого себя' });
    if (!read(F.users).some(u => u.id === target)) return res.status(404).json({ error: 'Пользователь не найден' });
    const blocks = read(F.blocks);
    blocks[me] = [...new Set([...(blocks[me] || []), target])];
    write(F.blocks, blocks);
    res.json({ success: true });
});

app.post('/api/unblock/:userId', (req, res) => {
    const me = req.uid, target = Number(req.params.userId);
    const blocks = read(F.blocks);
    blocks[me] = (blocks[me] || []).filter(id => id !== target);
    write(F.blocks, blocks);
    res.json({ success: true });
});

// ---------- Имена контактов («Мама» и т.п.) — видит только тот, кто задал ----------
app.get('/api/contacts', (req, res) => {
    const u = read(F.users).find(x => x.id === req.uid);
    res.json((u && u.contactNames) || {});
});

app.put('/api/contacts/:userId', (req, res) => {
    const me = req.uid, target = Number(req.params.userId);
    if (!read(F.users).some(u => u.id === target)) return res.status(404).json({ error: 'Пользователь не найден' });
    const users = read(F.users), u = users.find(x => x.id === me);
    if (!u) return res.status(401).json({ error: 'Войдите в аккаунт' });
    const name = String(req.body.name || '').trim().slice(0, 40);
    u.contactNames = u.contactNames || {};
    if (name) u.contactNames[target] = name; else delete u.contactNames[target];
    if (name && u.contactsHidden) u.contactsHidden = u.contactsHidden.filter(x => x !== target);
    write(F.users, users);
    res.json(u.contactNames);
});

// ---------- Список контактов ----------
// Контакт = добавлен вручную, или задано своё имя, или есть личная переписка. Убранные вручную скрываются.
function contactIds(u) {
    const ids = new Set([...(u.contacts || []), ...Object.keys(u.contactNames || {}).map(Number)]);
    read(F.chats).forEach(c => { if (c.type === 'direct' && (c.members || []).includes(u.id)) c.members.forEach(m => { if (m !== u.id) ids.add(m); }); });
    (u.contactsHidden || []).forEach(id => { if (!(u.contacts || []).includes(id)) ids.delete(id); });
    return ids;
}
app.get('/api/contacts/list', (req, res) => {
    const users = read(F.users), me = users.find(x => x.id === req.uid);
    if (!me) return res.status(401).json({ error: 'Войдите в аккаунт' });
    const ids = contactIds(me);
    const list = users.filter(u => ids.has(u.id) && !u.bot && !u.fake && !u.banned && u.id !== me.id).map(u => ({ ...pub(u), added: (me.contacts || []).includes(u.id), invited: u.invitedBy === me.id }));
    res.json({ list, invited: users.filter(u => u.invitedBy === me.id && !u.banned).length });
});
app.post('/api/contacts/add', (req, res) => {
    const users = read(F.users), me = users.find(x => x.id === req.uid);
    if (!me) return res.status(401).json({ error: 'Войдите в аккаунт' });
    const h = String((req.body || {}).handle || '').trim().replace(/^@/, '').toLowerCase();
    const id = Number((req.body || {}).targetUserId);
    const t = users.find(u => !u.fake && !u.bot && !u.banned && (id ? u.id === id : (u.handles || [u.handle]).includes(h)));
    if (!t) return res.status(404).json({ error: 'Пользователь не найден' });
    if (t.id === me.id) return res.status(400).json({ error: 'Это вы 🙂' });
    me.contacts = [...new Set([...(me.contacts || []), t.id])].slice(-2000);
    if (me.contactsHidden) me.contactsHidden = me.contactsHidden.filter(x => x !== t.id);
    write(F.users, users);
    res.json({ success: true, user: { ...pub(t), added: true } });
});
app.post('/api/contacts/:id/remove', (req, res) => {
    const users = read(F.users), me = users.find(x => x.id === req.uid), id = Number(req.params.id);
    if (!me) return res.status(401).json({ error: 'Войдите в аккаунт' });
    me.contacts = (me.contacts || []).filter(x => x !== id);
    if (me.contactNames) delete me.contactNames[id];
    me.contactsHidden = [...new Set([...(me.contactsHidden || []), id])].slice(-2000);
    write(F.users, users);
    res.json({ success: true, names: me.contactNames || {} });
});

app.get('/api/blocks', (req, res) => {
    const ids = blocksOf(req.uid), users = read(F.users);
    res.json({ blocked: ids, users: ids.map(id => users.find(u => u.id === id)).filter(Boolean).map(pub) });
});

