// ---------- Медиа, ссылки и голосовые чата (шторка в профиле) ----------
const SH_URL_RE = new RegExp(LP_URL_RE.source, 'gi');
function sharedLinks(text) {
    const out = [], seen = new Set();
    for (const m of String(text || '').matchAll(SH_URL_RE)) {
        const raw = m[2], url = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
        if (!seen.has(url) && out.length < 10) { seen.add(url); out.push(url); }
    }
    return out;
}
// В какие вкладки попадает сообщение (фото с подписью-ссылкой — и в «Медиа», и в «Ссылки»)
const sharedTabs = m => {
    if (m.sys || m.gift || m.deleted) return [];
    const out = [], md = m.media;
    if (md && !md.sticker) {
        if (md.kind === 'voice' || md.circle) out.push('voice');
        else if (md.kind === 'image' || md.kind === 'video') out.push('media');
    }
    if (m.text && LP_URL_RE.test(m.text)) out.push('links');
    return out;
};
// ---------- Экспорт чата: вся история по страницам (в хронологическом порядке) ----------
app.get('/api/chats/:id/export', (req, res) => {
    const me = req.uid;
    const chat = read(F.chats).find(c => String(c.id) === req.params.id);
    if (!chat || !chat.members.includes(me)) return res.status(403).json({ error: 'Нет доступа' });
    const clr = (chat.cleared || {})[me] || '';
    const since = /^\d{4}-\d\d-\d\dT/.test(String(req.query.since || '')) ? String(req.query.since) : '';
    const limit = Math.max(1, Math.min(2000, Number(req.query.limit) || 1000));
    const all = read(F.messages).filter(m => m.chatId === chat.id && m.timestamp > clr && (!since || m.timestamp >= since));
    // курсор — id последнего полученного сообщения; если его удалили во время экспорта — продолжаем по времени
    let start = 0;
    const after = String(req.query.after || ''), afterTs = String(req.query.afterTs || '');
    if (after) {
        const i = all.findIndex(m => m.id === after);
        start = i >= 0 ? i + 1 : (afterTs ? all.findIndex(m => m.timestamp > afterTs) : all.length);
        if (start < 0) start = all.length;
    }
    const page = all.slice(start, start + limit);
    const users = read(F.users), uix = new Map(users.map(u => [u.id, u]));
    const people = {};
    page.forEach(m => { const u = uix.get(m.senderId); if (u && !people[u.id]) people[u.id] = { id: u.id, name: u.username, handle: u.handle || '' }; });
    const items = page.map(m => { const o = outMsg(m, chat); const { viewers, fv, comments, ca, ...rest } = o; return rest; });
    let info;
    if (start === 0) {
        const peer = chat.type === 'direct' ? uix.get(chat.members.find(x => x !== me)) : null;
        info = { id: chat.id, type: chat.type, title: chat.type === 'saved' ? 'Избранное' : chat.type === 'direct' ? (peer ? peer.username : 'Удалённый аккаунт') : (chat.name || 'Чат'),
            handle: chat.type === 'direct' ? (peer && peer.handle) || '' : chat.handle || '', members: (chat.members || []).length, createdAt: chat.createdAt || null };
    }
    res.json({ total: all.length, items, users: people, done: start + page.length >= all.length, ...(info && { chat: info }) });
});

app.get('/api/chats/:id/shared', (req, res) => {
    const me = req.uid;
    const chat = read(F.chats).find(c => String(c.id) === req.params.id);
    if (!chat || !chat.members.includes(me)) return res.status(403).json({ error: 'Нет доступа' });
    const tab = ['media', 'links', 'voice'].includes(req.query.tab) ? req.query.tab : 'media';
    const limit = Math.max(1, Math.min(90, Number(req.query.limit) || 60));
    const before = String(req.query.before || ''); // id последнего показанного сообщения (следующая страница)
    const clr = (chat.cleared || {})[me] || '';
    const counts = { media: 0, links: 0, voice: 0 }, picked = [];
    const all = read(F.messages);
    let open = !before || !all.some(m => m.id === before); // страница «после» сообщения before (в порядке ленты)
    for (let i = all.length - 1; i >= 0; i--) {
        const m = all[i];
        if (m.chatId !== chat.id || m.timestamp <= clr) continue;
        const ts = sharedTabs(m);
        if (!ts.length) continue;
        for (const t of ts) counts[t]++;
        if (ts.includes(tab) && open && picked.length <= limit) picked.push(m);
        if (m.id === before) open = true;
    }
    const more = picked.length > limit; if (more) picked.length = limit;
    const ix = lazyIdx(), isFeed = chat.type === 'channel' && !chat.open;
    const from = m => { if (isFeed) return { id: 0, name: chat.name || 'Канал' }; const u = ix().get(m.senderId); return { id: m.senderId, name: u ? u.username : 'Удалённый аккаунт' }; };
    const items = [];
    for (const m of picked) {
        const base = { id: m.id, at: m.timestamp, from: from(m) };
        if (tab === 'links') {
            for (const url of sharedLinks(m.text)) {
                const pv = m.preview && m.preview.url === url ? m.preview : null;
                items.push({ ...base, url, text: String(m.text).slice(0, 200), ...(pv && { preview: { site: pv.site, title: pv.title, desc: pv.desc, img: pv.img } }) });
            }
        } else {
            const md = m.media;
            items.push({ ...base, kind: md.circle ? 'circle' : md.kind, url: md.url, ...(md.w && { w: md.w, h: md.h }), ...(md.dur && { dur: md.dur }), ...(m.text && tab === 'media' && { text: String(m.text).slice(0, 120) }) });
        }
    }
    res.json({ tab, counts, items, more, next: picked.length ? picked[picked.length - 1].id : null });
});

// ---------- Удаление и редактирование сообщений ----------
const chatOf = id => read(F.chats).find(c => c.id === id);

app.delete('/api/messages/:messageId', (req, res) => {
    const me = req.uid, messages = read(F.messages);
    const msg = messages.find(m => m.id === req.params.messageId);
    if (!msg) return res.status(404).json({ error: 'Сообщение не найдено' });
    if (msg.senderId !== me) return res.status(403).json({ error: 'Можно удалять только свои сообщения' });
    write(F.messages, messages.filter(m => m !== msg));
    const chat = chatOf(msg.chatId);
    sendTo(chat ? chat.members : [me], { type: 'messageDeleted', data: { chatId: msg.chatId, messageId: msg.id } });
    res.json({ success: true });
});

app.put('/api/messages/:messageId', (req, res) => {
    const me = req.uid, messages = read(F.messages);
    const msg = messages.find(m => m.id === req.params.messageId);
    if (!msg) return res.status(404).json({ error: 'Сообщение не найдено' });
    if (msg.senderId !== me) return res.status(403).json({ error: 'Можно изменять только свои сообщения' });
    if (msg.gift) return res.status(400).json({ error: 'Подарок изменить нельзя' });
    const text = String(req.body.text || '').trim().slice(0, 4000);
    if (!text && !msg.media) return res.status(400).json({ error: 'Текст не может быть пустым' });
    msg.text = text;
    msg.edited = new Date().toISOString();
    write(F.messages, messages);
    const chat = chatOf(msg.chatId);
    sendTo(chat ? chat.members : [me], { type: 'messageEdited', data: { chatId: msg.chatId, messageId: msg.id, text, edited: msg.edited } });
    if (msg.preview && !firstUrl(text)) { delete msg.preview; write(F.messages, messages); sendTo(chat ? chat.members : [me], { type: 'msgPreview', data: { chatId: msg.chatId, messageId: msg.id, preview: null } }); }
    attachPreview(msg.id);
    res.json({ success: true });
});

// ---------- Комментарии к постам канала ----------
const cmOut = (c, ix) => { const u = ix().get(c.userId); return { id: c.id, userId: c.userId, text: c.text, at: c.at, u: u ? userLite(u) : { id: c.userId, username: 'Удалённый аккаунт', avatar: '' } }; };
// Пост ленты канала, к которому участник может писать комментарии
function postFor(req, res) {
    const messages = read(F.messages), msg = messages.find(m => m.id === req.params.messageId);
    const chat = msg && chatOf(msg.chatId);
    if (!msg || !chat || chat.type !== 'channel' || chat.open || !chat.members.includes(req.uid)) { res.status(404).json({ error: 'Пост не найден' }); return null; }
    return { messages, msg, chat };
}
app.get('/api/messages/:messageId/comments', (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const ix = lazyIdx(), list = p.msg.comments || [];
    res.json({ count: list.length, comments: list.slice(-200).map(c => cmOut(c, ix)) });
});
// ---------- Расшифровка голосовых и кружков ----------
function trTarget(req, res) {
    const msgs = read(F.messages), m = msgs.find(x => x.id === req.params.messageId);
    const chat = m && read(F.chats).find(c => c.id === m.chatId);
    if (!m || !chat || !chat.members.includes(req.uid)) { res.status(404).json({ error: 'Сообщение не найдено' }); return null; }
    if (!m.media || !(m.media.kind === 'voice' || m.media.circle)) { res.status(400).json({ error: 'Это не голосовое сообщение' }); return null; }
    return { msgs, m, chat };
}
function saveTranscript(t, text) {
    t.m.media.tr = String(text || '').trim().slice(0, 4000) || '…';
    write(F.messages, t.msgs);
    sendTo(t.chat.members, { type: 'transcript', data: { chatId: t.chat.id, messageId: t.m.id, text: t.m.media.tr } });
    return t.m.media.tr;
}
// Сохранить расшифровку, сделанную в браузере (первая сохранённая — общая для всех участников)
app.post('/api/messages/:messageId/transcript', async (req, res) => {
    const t = trTarget(req, res); if (!t) return;
    if (t.m.media.tr) return res.json({ text: t.m.media.tr });
    const text = saveTranscript(t, req.body.text);
    await persist();
    res.json({ text });
});
// Расшифровать на сервере (если настроен ключ)
const trBusy = new Map();
app.post('/api/messages/:messageId/transcribe', async (req, res) => {
    const t = trTarget(req, res); if (!t) return;
    if (t.m.media.tr) return res.json({ text: t.m.media.tr });
    if (!STT_KEY || typeof fetch !== 'function' || typeof FormData !== 'function') return res.status(501).json({ error: 'not_configured' });
    const id = t.m.id;
    try {
        if (!trBusy.has(id)) trBusy.set(id, (async () => {
            const name = path.basename(t.m.media.url), buf = await fs.promises.readFile(path.join(UP, name));
            const fd = new FormData();
            fd.append('file', new Blob([buf]), name);
            fd.append('model', STT_MODEL);
            fd.append('response_format', 'json');
            const r = await fetch(STT_URL, { method: 'POST', headers: { Authorization: 'Bearer ' + STT_KEY }, body: fd });
            const d = await r.json().catch(() => ({}));
            if (!r.ok) throw new Error((d.error && d.error.message) || 'STT ' + r.status);
            return String(d.text || '');
        })().finally(() => setTimeout(() => trBusy.delete(id), 1000)));
        const text = await trBusy.get(id);
        const fresh = trTarget(req, res); if (!fresh) return;
        const out = fresh.m.media.tr || saveTranscript(fresh, text);
        await persist();
        res.json({ text: out });
    } catch (e) {
        console.error('transcribe:', e.message);
        res.status(502).json({ error: 'Не удалось расшифровать: ' + e.message });
    }
});

app.post('/api/messages/:messageId/comments', async (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const text = String(req.body.text || '').trim().slice(0, 500);
    if (!text) return res.status(400).json({ error: 'Напишите комментарий' });
    const c = { id: crypto.randomUUID(), userId: req.uid, text, at: new Date().toISOString() };
    p.msg.comments = (p.msg.comments || []).concat(c).slice(-1000);
    write(F.messages, p.messages);
    const ix = lazyIdx(), o = outMsg(p.msg, p.chat, ix), out = cmOut(c, ix);
    sendTo(p.chat.members, { type: 'comments', data: { chatId: p.chat.id, messageId: p.msg.id, cc: o.cc, ca: o.ca || [], comment: out } });
    await persist();
    res.json({ success: true, comment: out });
});
app.delete('/api/messages/:messageId/comments/:cid', async (req, res) => {
    const p = postFor(req, res); if (!p) return;
    const c = (p.msg.comments || []).find(x => x.id === req.params.cid);
    if (!c) return res.status(404).json({ error: 'Комментарий не найден' });
    if (c.userId !== req.uid && p.chat.creator !== req.uid) return res.status(403).json({ error: 'Нельзя удалить чужой комментарий' });
    p.msg.comments = p.msg.comments.filter(x => x !== c);
    write(F.messages, p.messages);
    const o = outMsg(p.msg, p.chat);
    sendTo(p.chat.members, { type: 'comments', data: { chatId: p.chat.id, messageId: p.msg.id, cc: o.cc, ca: o.ca || [], removed: c.id } });
    await persist();
    res.json({ success: true });
});

// Реакция на сообщение: одна на человека; тот же смайл ещё раз — снять
app.post('/api/messages/:messageId/react', async (req, res) => {
    const me = req.uid, emoji = String(req.body.emoji || '');
    if (!REACTIONS.includes(emoji)) return res.status(400).json({ error: 'Такой реакции нет' });
    const messages = read(F.messages), msg = messages.find(m => m.id === req.params.messageId);
    const chat = msg && chatOf(msg.chatId);
    if (!msg || !chat || !chat.members.includes(me)) return res.status(404).json({ error: 'Сообщение не найдено' });
    if (chat.type === 'direct') {
        const other = chat.members.find(i => i !== me);
        if (other === BOT_ID || (other && blockedEither(me, other))) return res.status(400).json({ error: 'Нельзя поставить реакцию' });
    }
    const r = msg.reactions = msg.reactions || {};
    const had = (r[emoji] || []).includes(me);
    for (const e of Object.keys(r)) { r[e] = r[e].filter(id => id !== me); if (!r[e].length) delete r[e]; }
    if (!had) (r[emoji] = r[emoji] || []).push(me);
    if (!Object.keys(r).length) delete msg.reactions;
    write(F.messages, messages);
    sendTo(chat.members, { type: 'reaction', data: { chatId: msg.chatId, messageId: msg.id, reactions: msg.reactions || {} } });
    await persist();
    res.json({ success: true });
});

// ---------- Удаление чатов ----------
// Личный: «у меня» скрывает историю только для меня, both=1 удаляет у обоих.
// Группа: выйти (создатель с both=1 удаляет для всех). Канал: автор удаляет, подписчик отписывается.
app.delete('/api/chats/:chatId', async (req, res) => {
    const me = req.uid, both = req.query.both === '1';
    const chats = read(F.chats), chat = chats.find(c => String(c.id) === req.params.chatId);
    if (!chat || !chat.members.includes(me)) return res.status(404).json({ error: 'Чат не найден' });
    const members = [...chat.members];
    const dropAll = () => {
        write(F.chats, chats.filter(c => c !== chat));
        write(F.messages, read(F.messages).filter(m => m.chatId !== chat.id));
    };
    const leave = () => {
        chat.members = chat.members.filter(id => id !== me);
        if (chat.members.length) write(F.chats, chats); else dropAll();
    };
    if (chat.type === 'direct') {
        if (both) dropAll();
        else { chat.cleared = chat.cleared || {}; chat.cleared[me] = new Date().toISOString(); write(F.chats, chats); }
    } else if (chat.type === 'group') {
        if (both && chat.creator === me) dropAll(); else leave();
    } else if (chat.creator === me) dropAll();
    else leave();
    sendTo(members, { type: 'chat' });
    await persist();
    res.json({ success: true });
});

// ---------- Админ-панель (доступна только аккаунту с юзернеймом ADMIN_HANDLE) ----------
const ADMIN_HANDLES = ['saimon'];
const ADMIN_HANDLE = 'saimon'; // главный (нельзя заблокировать/удалить)
const isAdminUid = uid => { const u = read(F.users).find(x => x.id === uid); return !!u && ADMIN_HANDLES.includes(u.handle); };
// Пароль админ-панели: спрашивается у админа перед входом и проверяется сервером при каждом запросе.
// Меняется через ADMIN_PIN=новый_пароль, по умолчанию 8015.
const ADMIN_PIN = process.env.ADMIN_PIN || '8015';
const adminOnly = (req, res, next) => {
    if (!isAdminUid(req.uid)) return res.status(403).json({ error: 'Нет доступа' });
    const pin = String(req.headers['x-admin-pin'] || req.query.pin || '');
    if (pin !== ADMIN_PIN) return res.status(403).json({ error: 'Неверный пароль админ-панели' });
    next();
};

// ---------- Антиспам ----------
// Флуд (больше 8 сообщений за 10 секунд), одно и то же сообщение 5 раз за 2 минуты,
// одна ссылка в 4+ разных чата → отправка приостанавливается: 30 сек → 2 мин → 10 мин → 1 час.
const SPAM = new Map(); // uid → { t: [время], h: [{n, at, c}], until, strikes, lastStrike }
const spamFmt = ms => ms >= 3600000 ? Math.round(ms / 3600000) + ' ч' : ms >= 60000 ? Math.round(ms / 60000) + ' мин' : Math.ceil(ms / 1000) + ' сек';
let spamSaveT = null;
function spamCheck(uid, chat, text) {
    if (isAdminUid(uid)) return null;
    const now = Date.now();
    const mu = meta.mutes && meta.mutes[uid];
    if (mu && mu > now) return `🔇 По жалобам вам запрещено писать сообщения ещё ${spamFmt(mu - now)}`;
    let st = SPAM.get(uid);
    if (!st) { st = { t: [], h: [], until: 0, strikes: 0, lastStrike: 0 }; SPAM.set(uid, st); }
    if (now < st.until) return `🧯 Отправка сообщений приостановлена ещё на ${spamFmt(st.until - now)} — похоже на спам`;
    st.t = st.t.filter(x => now - x < 10000); st.t.push(now);
    st.h = st.h.filter(x => now - x.at < 120000);
    const norm = String(text || '').toLowerCase().replace(/\s+/g, ' ').trim();
    let reason = null;
    if (st.t.length > 8) reason = 'слишком много сообщений подряд';
    if (!reason && norm.length >= 2) {
        const same = st.h.filter(x => x.n === norm);
        if (/https?:\/\/|www\.|[a-zа-я0-9-]+\.[a-zа-я]{2,}\//i.test(norm) && new Set([...same.map(x => x.c), chat.id]).size >= 4) reason = 'одна ссылка во много чатов';
        else if (same.length >= 4) reason = 'одно и то же сообщение много раз';
    }
    if (norm) st.h.push({ n: norm, at: now, c: chat.id });
    if (st.h.length > 60) st.h.splice(0, st.h.length - 60);
    if (!reason) return null;
    if (now - st.lastStrike > 3600000) st.strikes = 0;
    st.strikes++; st.lastStrike = now;
    const dur = [30000, 120000, 600000, 3600000][Math.min(3, st.strikes - 1)];
    st.until = now + dur; st.t = [];
    const u = read(F.users).find(x => x.id === uid);
    meta.spamLog = [...(meta.spamLog || []), { uid, name: u ? u.username : '?', handle: u ? u.handle || '' : '', reason, at: new Date(now).toISOString(), dur, strikes: st.strikes, sample: norm.slice(0, 120) }].slice(-200);
    clearTimeout(spamSaveT); spamSaveT = setTimeout(() => saveMeta(), 3000);
    return `🧯 Похоже на спам (${reason}). Отправка сообщений приостановлена на ${spamFmt(dur)}`;
}
app.get('/api/admin/spam', adminOnly, (req, res) => {
    const now = Date.now(), users = read(F.users);
    const active = [...SPAM].filter(([, st]) => st.until > now).map(([uid, st]) => { const u = users.find(x => x.id === uid); return { uid, name: u ? u.username : '?', handle: u ? u.handle || '' : '', left: st.until - now, strikes: st.strikes }; });
    for (const [k, until] of Object.entries(meta.mutes || {})) { const uid = Number(k); if (until > now && !active.some(a => a.uid === uid)) { const u = users.find(x => x.id === uid); active.push({ uid, name: u ? u.username : '?', handle: u ? u.handle || '' : '', left: until - now, strikes: 0, report: true }); } }
    res.json({ active, log: (meta.spamLog || []).slice(-50).reverse() });
});
app.post('/api/admin/spam/:uid/unmute', adminOnly, (req, res) => {
    const st = SPAM.get(Number(req.params.uid));
    if (st) { st.until = 0; st.strikes = 0; st.t = []; st.h = []; }
    if (meta.mutes && meta.mutes[req.params.uid]) { delete meta.mutes[req.params.uid]; saveMeta(); }
    res.json({ success: true });
});

// ---------- Жалобы ----------
// Пользователь жалуется на сообщение или на человека → жалоба попадает в админ-панель (только @saimon).
// Жалобы на одно и то же объединяются; админ решает: отклонить, удалить сообщение, предупредить, запретить писать, заблокировать.
const REPORT_REASONS = { spam: 'Спам', abuse: 'Оскорбления, травля', scam: 'Мошенничество', nsfw: '18+ или жестокость', fake: 'Выдаёт себя за другого', other: 'Другое' };
const repRate = new Map(); // uid → [время]
const repKey = r => r.kind === 'msg' ? 'm:' + r.msgId : 'u:' + r.targetUid;
const repOpen = () => (meta.reports || []).filter(r => r.status === 'open');
function repNotifyAdmins() {
    const n = repOpen().length;
    const admins = read(F.users).filter(u => ADMIN_HANDLES.includes(u.handle)).map(u => u.id);
    sendTo(admins, { type: 'reports', data: { open: n } });
    return admins;
}
app.post('/api/reports', async (req, res) => {
    const me = req.uid, b = req.body || {};
    const users = read(F.users), meU = users.find(u => u.id === me);
    if (!meU || meU.banned) return res.status(403).json({ error: 'Нет доступа' });
    const reason = REPORT_REASONS[b.reason] ? b.reason : null;
    if (!reason) return res.status(400).json({ error: 'Выберите причину' });
    const note = String(b.note || '').trim().slice(0, 500);
    const now = Date.now();
    const rl = (repRate.get(me) || []).filter(t => now - t < 3600000);
    if (rl.length >= 15) return res.status(429).json({ error: 'Слишком много жалоб, попробуйте позже' });
    let rep;
    if (b.msgId) {
        const msg = read(F.messages).find(m => m.id === String(b.msgId));
        if (!msg) return res.status(404).json({ error: 'Сообщение не найдено' });
        const chat = chatOf(msg.chatId);
        if (!chat || !(chat.members || []).includes(me)) return res.status(403).json({ error: 'Нет доступа к этому чату' });
        if (msg.senderId === me) return res.status(400).json({ error: 'Нельзя пожаловаться на своё сообщение' });
        const au = users.find(u => u.id === msg.senderId);
        if (!au || au.bot || isAdminUid(au.id)) return res.status(400).json({ error: 'На это сообщение пожаловаться нельзя' });
        rep = { kind: 'msg', msgId: msg.id, chatId: chat.id, targetUid: msg.senderId,
            chatName: chat.type === 'direct' ? 'Личный чат' : (chat.name || 'Чат'), chatType: chat.type,
            msg: { text: String(msg.text || '').slice(0, 1000), media: msg.media ? { kind: msg.media.kind, url: msg.media.url } : null, at: msg.timestamp } };
    } else {
        const uid = Number(b.targetUserId);
        const tu = users.find(u => u.id === uid);
        if (!tu || tu.bot || tu.fake) return res.status(404).json({ error: 'Пользователь не найден' });
        if (uid === me) return res.status(400).json({ error: 'Нельзя пожаловаться на себя' });
        if (isAdminUid(uid)) return res.status(400).json({ error: 'На этот аккаунт пожаловаться нельзя' });
        rep = { kind: 'user', targetUid: uid };
    }
    meta.reports = meta.reports || [];
    const key = repKey(rep);
    let r = meta.reports.find(x => x.status === 'open' && x.key === key);
    const first = !r;
    if (!r) { r = { id: crypto.randomUUID().slice(0, 12), key, ...rep, status: 'open', by: [], createdAt: new Date(now).toISOString() }; meta.reports.push(r); }
    if (r.by.some(x => x.uid === me)) return res.json({ success: true, already: true });
    r.by.push({ uid: me, reason, note, at: new Date(now).toISOString() });
    r.updatedAt = new Date(now).toISOString();
    rl.push(now); repRate.set(me, rl);
    // храним последние 1000: сначала выкидываем закрытые
    if (meta.reports.length > 1000) { const closed = meta.reports.filter(x => x.status !== 'open'); const drop = new Set(closed.slice(0, meta.reports.length - 1000).map(x => x.id)); meta.reports = meta.reports.filter(x => !drop.has(x.id)); }
    await saveMeta();
    const admins = repNotifyAdmins();
    if (first) {
        const tu = users.find(u => u.id === r.targetUid);
        const who = tu ? `${tu.username}${tu.handle ? ' (@' + tu.handle + ')' : ''}` : 'пользователя';
        admins.forEach(a => scBotSay(a, `🚩 Новая жалоба: ${REPORT_REASONS[reason]} — на ${r.kind === 'msg' ? 'сообщение ' : ''}${who}. Откройте Админ-панель → Жалобы.`));
    }
    res.json({ success: true });
});
const repUser = (users, id) => { const u = users.find(x => x.id === id); if (!u) return { id, name: '?' }; const name = u.banned && u.banBackup ? u.banBackup.username : u.username, handle = u.banned && u.banBackup ? u.banBackup.handle : u.handle; return { id, name, handle: handle || '', avatar: u.banned ? '' : (u.avatar || ''), banned: !!u.banned, createdAt: u.createdAt }; };
app.get('/api/admin/reports/count', (req, res) => {
    if (!isAdminUid(req.uid)) return res.status(403).json({ error: 'Нет доступа' });
    res.json({ open: repOpen().length });
});
app.get('/api/admin/reports', adminOnly, (req, res) => {
    const users = read(F.users), done = req.query.status === 'done';
    const all = meta.reports || [];
    const list = all.filter(r => done ? r.status !== 'open' : r.status === 'open')
        .sort((a, b) => done ? String(b.closedAt).localeCompare(String(a.closedAt)) : (b.by.length - a.by.length) || String(b.updatedAt).localeCompare(String(a.updatedAt)))
        .slice(0, 100)
        .map(r => {
            const prev = all.filter(x => x.targetUid === r.targetUid && x.status === 'done' && x.action && x.action !== 'dismiss').length;
            const mu = meta.mutes && meta.mutes[r.targetUid];
            return { ...r, target: repUser(users, r.targetUid), prev, mutedLeft: mu && mu > Date.now() ? mu - Date.now() : 0,
                msgGone: r.kind === 'msg' && !read(F.messages).some(m => m.id === r.msgId),
                by: r.by.map(x => ({ ...x, reasonName: REPORT_REASONS[x.reason], user: repUser(users, x.uid) })) };
        });
    res.json({ list, open: repOpen().length, reasons: REPORT_REASONS });
});
app.post('/api/admin/reports/:id/act', adminOnly, async (req, res) => {
    const r = (meta.reports || []).find(x => x.id === req.params.id);
    if (!r) return res.status(404).json({ error: 'Жалоба не найдена' });
    if (r.status !== 'open') return res.status(400).json({ error: 'Жалоба уже рассмотрена' });
    const act = String((req.body || {}).action || '');
    const ACTS = { dismiss: 'Отклонена', delete: 'Сообщение удалено', warn: 'Предупреждение', mute1: 'Запрет писать на 1 день', mute7: 'Запрет писать на 7 дней', ban: 'Аккаунт заблокирован' };
    if (!ACTS[act]) return res.status(400).json({ error: 'Неизвестное действие' });
    const del = act !== 'dismiss' && r.kind === 'msg' && ((req.body || {}).del !== false);
    if (del) {
        const messages = read(F.messages), msg = messages.find(m => m.id === r.msgId);
        if (msg) {
            write(F.messages, messages.filter(m => m !== msg));
            const chat = chatOf(msg.chatId);
            if (chat) sendTo(chat.members, { type: 'messageDeleted', data: { chatId: msg.chatId, messageId: msg.id } });
        }
    }
    const reasonName = REPORT_REASONS[r.by[0] && r.by[0].reason] || 'нарушение правил';
    if (act === 'warn') scBotSay(r.targetUid, `⚠️ Предупреждение от администрации SAIMON.\nНа вас пожаловались: ${reasonName.toLowerCase()}.${del ? ' Сообщение удалено.' : ''}\nПри повторных нарушениях отправка сообщений будет ограничена, а аккаунт — заблокирован.`);
    if (act === 'mute1' || act === 'mute7') {
        const days = act === 'mute1' ? 1 : 7;
        meta.mutes = meta.mutes || {};
        meta.mutes[r.targetUid] = Math.max(meta.mutes[r.targetUid] || 0, Date.now() + days * 864e5);
        scBotSay(r.targetUid, `🔇 По жалобам пользователей (${reasonName.toLowerCase()}) вы не можете отправлять сообщения ${days === 1 ? '1 день' : '7 дней'}.${del ? ' Сообщение удалено.' : ''}`);
    }
    if (act === 'ban') { const err = await banUser(r.targetUid); if (err) return res.status(400).json({ error: err }); }
    const closeOne = (x, a) => { x.status = 'done'; x.action = a; x.closedAt = new Date().toISOString(); x.closedBy = req.uid; };
    closeOne(r, act);
    if (del) r.deleted = true;
    // при бане закрываем и остальные жалобы на этого человека
    if (act === 'ban') (meta.reports || []).forEach(x => { if (x.status === 'open' && x.targetUid === r.targetUid) closeOne(x, 'ban'); });
    if (act !== 'dismiss') {
        const thanked = new Set();
        (meta.reports || []).filter(x => x.closedAt && x.targetUid === r.targetUid && x.action === act && (x === r || act === 'ban')).forEach(x => x.by.forEach(b => {
            if (thanked.has(b.uid)) return; thanked.add(b.uid);
            try { scBotSay(b.uid, '✅ Спасибо за жалобу! Мы её рассмотрели и приняли меры.'); } catch {}
        }));
    }
    await saveMeta(); await persist();
    repNotifyAdmins();
    res.json({ success: true, label: ACTS[act] });
});

// ---------- Статистика сервера (админ) ----------
const SERVER_START = Date.now();
app.get('/api/admin/stats', adminOnly, (req, res) => {
    const now = Date.now(), tz = Math.max(-840, Math.min(840, Number(req.query.tz) || 0)) * 60000; // смещение часового пояса админа
    const dayKey = t => new Date(t + tz).toISOString().slice(0, 10);
    const DAYS = 14, days = [];
    for (let i = DAYS - 1; i >= 0; i--) days.push(dayKey(now - i * 86400000));
    const today = days[DAYS - 1], idx = new Map(days.map((d, i) => [d, i]));
    const users = read(F.users), real = users.filter(u => !u.bot && !u.fake);
    const regs = Array(DAYS).fill(0), msgsD = Array(DAYS).fill(0), activeD = days.map(() => new Set());
    for (const u of real) { const t = Date.parse(u.createdAt || ''); const i = t ? idx.get(dayKey(t)) : undefined; if (i !== undefined) regs[i]++; }
    const msgs = read(F.messages), botIds = new Set(users.filter(u => u.bot).map(u => u.id));
    let calls = 0, media = 0, msgTotal = 0;
    const senders7 = new Map(), weekAgo = now - 7 * 86400000;
    for (const m of msgs) {
        if (m.sys) continue;
        msgTotal++;
        const t = Date.parse(m.timestamp); if (!t) continue;
        const i = idx.get(dayKey(t));
        if (i !== undefined && !botIds.has(m.senderId)) { msgsD[i]++; activeD[i].add(m.senderId); if (i === DAYS - 1) { if (m.call) calls++; if (m.media) media++; } }
        if (t > weekAgo && !botIds.has(m.senderId)) senders7.set(m.senderId, (senders7.get(m.senderId) || 0) + 1);
    }
    const sess = Object.values(read(F.sessions));
    const seenSince = ms => new Set(sess.filter(x => (x.seen || x.at || 0) > now - ms).map(x => x.uid)).size;
    const onlineIds = [...sockets.keys()].filter(id => !botIds.has(id) && sockets.get(id).size);
    const chats = read(F.chats), gifts = read(F.gifts);
    const byName = id => { const u = users.find(x => x.id === id); return u ? { id, username: u.username, handle: u.handle || '' } : { id, username: 'Удалённый', handle: '' }; };
    res.json({
        days, regs, msgs: msgsD, active: activeD.map(s => s.size),
        users: { total: real.length, banned: real.filter(u => u.banned).length, premium: real.filter(u => premiumOn(u)).length, today: regs[DAYS - 1], week: regs.slice(-7).reduce((a, b) => a + b, 0) },
        online: { now: onlineIds.length, active: onlineIds.filter(id => [...sockets.get(id)].some(w => w.active)).length, day: seenSince(86400000), week: seenSince(7 * 86400000), month: seenSince(30 * 86400000) },
        messages: { total: msgTotal, today: msgsD[DAYS - 1], week: msgsD.slice(-7).reduce((a, b) => a + b, 0), calls, media },
        chats: { direct: chats.filter(c => c.type === 'direct').length, groups: chats.filter(c => c.type === 'group').length, channels: chats.filter(c => c.type === 'channel').length },
        economy: { mars: real.filter(u => !isUnlimited(u)).reduce((a, u) => a + (u.mars || 0), 0), gifts: gifts.length, lots: gifts.filter(g => g.listing).length, auctions: gifts.filter(g => g.auction).length },
        topChannels: chats.filter(c => c.type === 'channel').sort((a, b) => b.members.length - a.members.length).slice(0, 5).map(c => ({ name: c.name, handle: c.handle || '', subs: c.members.length })),
        topSenders: [...senders7].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([id, n]) => ({ ...byName(id), n })),
        server: { uptime: Math.round((now - SERVER_START) / 1000), rss: Math.round(process.memoryUsage().rss / 1048576), storage: pool ? 'PostgreSQL' : 'файлы', node: process.version }
    });
});

// ---------- Рассылка от SAIMON-CHAT всем пользователям (админ) ----------
let bcastBusy = false, bcastLast = 0;
const bcastAudience = (aud) => {
    const now = Date.now(), users = read(F.users).filter(u => !u.bot && !u.fake && !u.banned);
    if (aud !== 'active') return users;
    const act = new Set(Object.values(read(F.sessions)).filter(x => (x.seen || x.at || 0) > now - 30 * 86400000).map(x => x.uid));
    return users.filter(u => act.has(u.id));
};
app.get('/api/admin/broadcasts', adminOnly, (req, res) => {
    res.json({ history: (meta.broadcasts || []).slice(-20).reverse(), all: bcastAudience('all').length, active: bcastAudience('active').length });
});
app.post('/api/admin/broadcast', adminOnly, async (req, res) => {
    const text = String(req.body.text || '').trim().slice(0, 3000), aud = req.body.audience === 'active' ? 'active' : 'all', push = req.body.push !== false;
    if (text.length < 2) return res.status(400).json({ error: 'Напишите текст рассылки' });
    if (bcastBusy) return res.status(409).json({ error: 'Предыдущая рассылка ещё отправляется' });
    if (Date.now() - bcastLast < 60000) return res.status(429).json({ error: 'Рассылку можно отправлять не чаще раза в минуту' });
    const list = bcastAudience(aud);
    bcastBusy = true; bcastLast = Date.now();
    let sent = 0;
    try {
        const at = new Date().toISOString(), out = [], chatIds = new Set();
        for (const u of list) {
            const chat = scBotChat(u.id);
            const msg = { id: crypto.randomUUID(), chatId: chat.id, senderId: SC_BOT_ID, text, timestamp: at, bcast: true };
            out.push(msg); chatIds.add(chat.id);
            sendTo([u.id], { type: 'message', data: msg });
            if (push) notifyMessage(chat, msg, text);
            sent++;
            if (sent % 200 === 0) await new Promise(r => setImmediate(r)); // не блокируем сервер на больших рассылках
        }
        const all = read(F.messages); all.push(...out); write(F.messages, all); // дописываем в конец — сообщения, пришедшие во время рассылки, не теряются
        const cs = read(F.chats); cs.forEach(c => { if (chatIds.has(c.id)) { c.reads = c.reads || {}; c.reads[SC_BOT_ID] = at; } }); write(F.chats, cs);
        const by = read(F.users).find(x => x.id === req.uid);
        meta.broadcasts = [...(meta.broadcasts || []), { at, text: text.slice(0, 300), count: sent, audience: aud, by: by ? by.username : '' }].slice(-50);
        await saveMeta();
        await persist();
        res.json({ success: true, sent });
    } catch (e) {
        console.error('broadcast:', e.message);
        res.status(500).json({ error: 'Рассылка прервалась, отправлено: ' + sent });
    } finally { bcastBusy = false; }
});

