// ---------- WebSocket ----------
// ===== Звонки 1-на-1: пересылка сигналов WebRTC + запись звонка в чате =====
// call в сообщении: { status: 'ringing'|'active'|'ended'|'missed'|'declined'|'busy', dur?: секунды }
const CALL_TYPES = ['call_offer', 'call_answer', 'call_ice', 'call_end', 'call_reject', 'call_busy', 'call_cam'];
const CALL_RING_MS = 45000; // столько ждём ответа, потом «Нет ответа»
const calls = new Map();    // chatId -> { caller, callee, msgId, answeredAt, timer, ws:Set }

function saveCallMsg(chat, caller, call) {
    const msg = { id: crypto.randomUUID(), chatId: chat.id, senderId: caller, text: '', call, timestamp: new Date().toISOString() };
    const msgs = read(F.messages);
    msgs.push(msg);
    write(F.messages, msgs);
    sendTo(chat.members, { type: 'message', data: msg });
    return msg;
}
function updateCallMsg(chatId, msgId, call) {
    const msgs = read(F.messages), msg = msgs.find(x => x.id === msgId);
    if (!msg) return;
    msg.call = call;
    write(F.messages, msgs);
    const chat = read(F.chats).find(c => c.id === chatId);
    if (chat) sendTo(chat.members, { type: 'callUpdate', data: { chatId, messageId: msgId, call } });
}
function finishCall(chatId, byUid, status) {
    const call = calls.get(chatId);
    if (!call) return;
    calls.delete(chatId);
    clearTimeout(call.timer);
    const res = { status, ...(call.video && { video: true }) };
    if (status === 'ended' && call.answeredAt) res.dur = Math.max(0, Math.round((Date.now() - call.answeredAt) / 1000));
    updateCallMsg(chatId, call.msgId, res);
    // Обеим сторонам (всем их вкладкам) — сигнал, что звонок окончен
    sendTo([call.caller, call.callee], { type: 'call_end', data: { from: byUid, chatId, reason: status } });
    if (status === 'missed') {
        const chat = read(F.chats).find(c => c.id === chatId);
        if (chat) notifyMessage(chat, { senderId: call.caller }, '📞 Пропущенный звонок');
    }
}
const inCall = id => [...calls.values()].some(c => c.caller === id || c.callee === id);

function handleCallWs(uid, chat, m, ws) {
    if (chat.type !== 'direct') return;
    const toId = chat.members.find(i => i !== uid);
    if (!toId || toId === BOT_ID || blockedEither(uid, toId)) return;
    const d = m.data && typeof m.data === 'object' ? m.data : {};
    const call = calls.get(chat.id);
    const relay = () => sendTo([toId], { type: m.type, data: { ...d, from: uid, chatId: chat.id } });

    if (m.type === 'call_offer') {
        if (call) return;
        const callee = read(F.users).find(x => x.id === toId);
        if (!callee || !privOk(callee, 'privCall', uid))
            return ws.send(JSON.stringify({ type: 'call_end', data: { from: toId, chatId: chat.id, reason: 'privacy' } }));
        if (inCall(toId) || inCall(uid)) {
            saveCallMsg(chat, uid, { status: 'busy', ...(d.video === true && { video: true }) });
            return ws.send(JSON.stringify({ type: 'call_busy', data: { from: toId, chatId: chat.id } }));
        }
        const video = d.video === true;
        const msg = saveCallMsg(chat, uid, { status: 'ringing', ...(video && { video: true }) });
        calls.set(chat.id, {
            caller: uid, callee: toId, msgId: msg.id, answeredAt: 0, ws: new Set([ws]), video,
            timer: setTimeout(() => finishCall(chat.id, null, 'missed'), CALL_RING_MS)
        });
        relay();
        notifyMessage(chat, { senderId: uid }, video ? '📹 Входящий видеозвонок' : '📞 Входящий аудиозвонок');
    } else if (m.type === 'call_answer') {
        if (!call || uid !== call.callee || call.answeredAt) return;
        call.answeredAt = Date.now();
        call.ws.add(ws);
        clearTimeout(call.timer);
        updateCallMsg(chat.id, call.msgId, { status: 'active', ...(call.video && { video: true }) });
        relay();
        // Другие вкладки принявшего — убрать экран входящего звонка
        sendTo([uid], { type: 'call_end', data: { from: uid, chatId: chat.id, elsewhere: true } }, ws);
    } else if (m.type === 'call_ice' || m.type === 'call_cam') {
        if (call) relay();
    } else if (m.type === 'call_end') {
        if (!call) return;
        finishCall(chat.id, uid, call.answeredAt ? 'ended' : uid === call.caller ? 'missed' : 'declined');
    } else if (m.type === 'call_reject' || m.type === 'call_busy') {
        if (!call || uid !== call.callee || call.answeredAt) return;
        finishCall(chat.id, uid, m.type === 'call_busy' ? 'busy' : 'declined');
    }
}

wss.on('connection', ws => {
    let uid = null;
    ws.isAlive = true;
    ws.on('pong', () => { ws.isAlive = true; });
    ws.on('error', () => {}); // ошибка одного клиента не должна ронять сервер

    ws.on('message', raw => {
        try {
            const m = JSON.parse(raw);

            if (m.type === 'connect') {
                const sess = read(F.sessions)[m.token];
                if (!sess) { ws.send(JSON.stringify({ type: 'auth', data: { ok: false } })); return ws.close(); }
                uid = sess.uid;
                ws.token = m.token;
                ws.active = m.active !== false;
                if (!sockets.has(uid)) sockets.set(uid, new Set());
                sockets.get(uid).add(ws);
                broadcast({ type: 'presence', data: { userId: uid, online: true } });
                const u = read(F.users).find(x => x.id === uid);
                if (u) ws.send(JSON.stringify({ type: 'wallet', data: walletOf(u) }));
                return;
            }
            if (!uid) return;
            if (m.type === 'active') { ws.active = !!m.active; return; } // вкладка открыта и видна — идёт время для Mars

            const chats = read(F.chats);
            const chat = chats.find(c => String(c.id) === String(m.chatId));
            if (!chat || !chat.members.includes(uid)) return;

            if (m.type === 'message') {
                if (chat.type === 'channel' && chat.creator !== uid && !chat.open) return; // в канал пишет только автор (в текстовом — все)
                if (chat.type === 'direct') {
                    const other = chat.members.find(i => i !== uid);
                    if (other === BOT_ID || other === HOURS_ID) return; // с этими ботами общаются кнопками
                    if (other && blockedEither(uid, other)) {
                        return ws.send(JSON.stringify({ type: 'error', data: { cid: m.cid, text: iBlocked(uid, other) ? 'Вы заблокировали этого пользователя' : 'Не удалось отправить сообщение' } }));
                    }
                }
                const text = String(m.text || '').trim().slice(0, 4000);
                let media;
                if (m.media && fileOk(m.media.url)) {
                    const isSticker = m.media.sticker === true || m.media.kind === 'sticker';
                    media = { kind: isSticker ? 'sticker' : kindOf(m.media.url), url: m.media.url };
                    if (isSticker) media.sticker = true;
                    const w = Number(m.media.w), h = Number(m.media.h);
                    if (w > 0 && h > 0 && w < 20000 && h < 20000) { media.w = Math.round(w); media.h = Math.round(h); }
                    const dur = Number(m.media.dur);
                    if (media.kind === 'voice' && dur > 0 && dur < 3600) media.dur = Math.round(dur);
                    if (media.kind === 'video' && m.media.circle === true) { media.circle = true; if (dur > 0 && dur <= 61) media.dur = Math.round(dur); }
                }
                if (!text && !media) return;
                const spam = spamCheck(uid, chat, text);
                if (spam) return ws.send(JSON.stringify({ type: 'error', data: { cid: m.cid, text: spam } }));
                // Упоминания @юзернейм в группах и открытых каналах
                let mentions;
                if ((chat.type === 'group' || (chat.type === 'channel' && chat.open)) && /@[a-z0-9_]{3,20}/i.test(text)) {
                    const hs = new Set([...text.matchAll(/(^|[^a-zA-Z0-9_])@([a-zA-Z0-9_]{3,20})/g)].map(x => x[2].toLowerCase()));
                    const ids = read(F.users).filter(u => u.id !== uid && chat.members.includes(u.id) && (u.handles || [u.handle]).some(h => hs.has(h))).map(u => u.id);
                    if (ids.length) mentions = ids;
                }

                // Ответ на сообщение: сохраняем снапшот оригинала (переживёт его удаление)
                let reply;
                if (m.reply && typeof m.reply === 'object') {
                    const orig = read(F.messages).find(x => x.id === String(m.reply.id || '') && x.chatId === chat.id);
                    if (orig) {
                        const u = read(F.users).find(x => x.id === orig.senderId);
                        reply = { id: orig.id, name: u ? u.username : 'Удалённый аккаунт', ...(u ? { handle: u.handle } : {}),
                            text: String(orig.text || '').slice(0, 120), mk: orig.media ? (orig.media.circle ? 'circle' : orig.media.kind) : (orig.gift ? 'gift' : '') };
                    }
                }
                // Пересылка: помечаем, от кого оригинал
                let fwd;
                if (m.fwd && typeof m.fwd === 'object') {
                    const u = read(F.users).find(x => x.id === Number(m.fwd.from));
                    if (u) fwd = { from: u.id, name: u.username, handle: u.handle };
                }

                const msg = {
                    id: crypto.randomUUID(), chatId: chat.id, senderId: uid, text,
                    ...(media && { media }), ...(reply && { reply }), ...(fwd && { fwd }), ...(mentions && { mentions }), timestamp: new Date().toISOString()
                };
                if (chat.type === 'channel' && !chat.open) { msg.viewers = [uid]; msg.fv = rollFv(fakeInChannel(chat, read(F.users))); }
                const msgs = read(F.messages);
                msgs.push(msg);
                write(F.messages, msgs);
                sendTo(chat.members, { type: 'message', data: outMsg(msg, chat), cid: m.cid ? String(m.cid).slice(0, 40) : undefined }); // только участникам чата; cid — чтобы отправитель заменил своё временное
                notifyMessage(chat, msg);
                attachPreview(msg.id);
                if (chat.type === 'direct') onCustomBotMessage(chat, uid, msg);
                else if (chat.type === 'group') onGroupBotMessage(chat, uid, msg);

            } else if (m.type === 'read') {
                if (chat.type === 'channel' && !chat.open) markViews(chat, uid);
                // Помечаем прочитанным всё до последнего сообщения включительно
                const last = read(F.messages).filter(x => x.chatId === chat.id).pop();
                const at = last ? last.timestamp : '';
                chat.reads = chat.reads || {};
                if (!at || (chat.reads[uid] || '') >= at) return;
                chat.reads[uid] = at;
                write(F.chats, chats);
                const rUsers = read(F.users), rOff = id => (rUsers.find(x => x.id === id) || {}).readReceipts === false;
                const rTo = chat.members.filter(id => id === uid || (!rOff(uid) && !rOff(id)));
                sendTo(rTo, { type: 'read', data: { chatId: chat.id, userId: uid, at } });

            } else if (CALL_TYPES.includes(m.type)) {
                handleCallWs(uid, chat, m, ws);

            } else if (m.type === 'typing') {
                if (chat.type === 'channel') return;
                if (chat.type === 'direct' && blockedEither(uid, chat.members.find(i => i !== uid))) return;
                sendTo(chat.members, { type: 'typing', data: { chatId: chat.id, userId: uid } }, ws);

            } else if (m.type === 'emoji_tap') {
                // Нажатие на анимированный эмодзи — собеседник тоже видит эффект
                const now = Date.now();
                if (now - (ws.lastEmojiTap || 0) < 700) return;
                ws.lastEmojiTap = now;
                const emoji = String(m.emoji || '');
                if (!emoji || emoji.length > 24 || /[<>&"']/.test(emoji)) return;
                if (chat.type === 'direct' && blockedEither(uid, chat.members.find(i => i !== uid))) return;
                const tm = read(F.messages).find(x => x.id === m.messageId && String(x.chatId) === String(chat.id));
                if (!tm || !tm.text || !String(tm.text).includes(emoji)) return;
                sendTo(chat.members.filter(id => id !== uid), { type: 'emojiTap', data: { chatId: chat.id, messageId: tm.id, emoji, userId: uid } });
            }
        } catch (err) {
            console.error('WS error:', err);
        }
    });

    ws.on('close', () => {
        if (!uid || !sockets.has(uid)) return;
        sockets.get(uid).delete(ws);
        // Закрылась вкладка, на которой шёл звонок — завершаем его
        for (const [cid, call] of calls) {
            if (call.ws.has(ws)) finishCall(cid, uid, call.answeredAt ? 'ended' : uid === call.caller ? 'missed' : 'declined');
        }
        if (!sockets.get(uid).size) {
            sockets.delete(uid);
            // Сохраняем время последнего выхода
            const users = read(F.users);
            const offU = users.find(x => x.id === uid);
            if (offU) { offU.lastSeen = Date.now(); write(F.users, users); }
            broadcast({ type: 'presence', data: { userId: uid, online: false, lastSeen: offU ? offU.lastSeen : null } });
        }
    });
});

// Ошибки в JSON, чтобы клиент мог показать понятный текст
app.use((err, req, res, next) => {
    const big = err.type === 'entity.too.large';
    res.status(big ? 413 : err.status || 500).json({ error: big ? 'Файл слишком большой (максимум 50 МБ)' : 'Ошибка сервера' });
});

// Пинг раз в 25 секунд: хостинги закрывают «молчащие» соединения, а мёртвые мы убираем из «в сети»
setInterval(() => wss.clients.forEach(ws => {
    if (!ws.isAlive) return ws.terminate();
    ws.isAlive = false;
    ws.ping();
}), 25000);

// Mars за время: раз в минуту каждому, у кого приложение открыто и видно (несколько вкладок считаются за одну)
setInterval(() => {
    const ids = new Set();
    sockets.forEach((set, id) => { if ([...set].some(w => w.active)) ids.add(id); });
    if (!ids.size) return;
    const users = read(F.users);
    users.forEach(u => {
        if (!ids.has(u.id) || isUnlimited(u)) return;
        u.mars = (u.mars || 0) + MARS_PER_MIN;
        sendTo([u.id], { type: 'wallet', data: walletOf(u) });
    });
    write(F.users, users);
}, 60000);

process.on('uncaughtException', e => console.error('Необработанная ошибка:', e));
process.on('unhandledRejection', e => console.error('Необработанный промис:', e));

// Диагностика: проверяем прямо при старте, что ffmpeg вообще запускается на этом хостинге,
// и пишем явный результат в лог — чтобы при проблемах с видео/голосовыми не гадать вслепую.
function checkFfmpeg() {
    const { execFile } = require('child_process');
    execFile(require('@ffmpeg-installer/ffmpeg').path, ['-version'], (err, stdout) => {
        if (err) console.error('🎬 ffmpeg НЕ запускается на этом хостинге, перекодирование видео/голосовых отключится автоматически:', err.message);
        else console.log('🎬 ffmpeg доступен:', String(stdout).split('\n')[0]);
    });
}

async function init() {
    checkFfmpeg();
    let hasMeta = false;
    if (process.env.DATABASE_URL) {
        const { Pool } = require('pg');
        const cs = new URL(process.env.DATABASE_URL);
        cs.searchParams.delete('channel_binding');
        cs.searchParams.delete('sslmode');
        const local = ['localhost', '127.0.0.1'].includes(cs.hostname);
        pool = new Pool({
            connectionString: cs.toString(), ssl: local ? false : { rejectUnauthorized: false },
            max: 4, keepAlive: true, connectionTimeoutMillis: 20000
        });
        pool.on('error', e => console.error('DB:', e.message)); // обрыв простаивающего соединения не должен ронять сервер
        await pool.query('create table if not exists kv (key text primary key, value jsonb not null, updated_at timestamptz not null default now())');
        await pool.query('create table if not exists files (name text primary key, data bytea not null, created_at timestamptz not null default now())');
        const { rows } = await pool.query('select key, value from kv');
        rows.forEach(r => {
            if (r.key === 'meta') { meta = r.value; hasMeta = true; } else mem[r.key] = JSON.stringify(r.value);
        });
    }
    // Чего нет в базе (первый запуск) — берём из локальных файлов, иначе пустой список
    for (const k of ['users', 'messages', 'chats', 'gifts', 'sessions', 'blocks', 'sticker_packs', 'bots']) {
        if (mem[k] === undefined) {
            const d = loadFile(F[k]);
            mem[k] = JSON.stringify((k === 'sessions' || k === 'blocks' || k === 'bots') && Array.isArray(d) ? {} : d); // объекты {токен: …}, {кто: [кого]}
            if (pool) dirty.add(k);
        }
    }
    if (pool) {
        if (!hasMeta) await pool.query("insert into kv (key, value) values ('meta', $1::jsonb) on conflict (key) do nothing", [JSON.stringify(meta)]);
    } else {
        const mf = path.join(DIR, 'meta.json');
        try { meta = JSON.parse(fs.readFileSync(mf, 'utf8')); } catch { fs.writeFileSync(mf, JSON.stringify(meta)); }
    }
    migrate();
    purgeBotAccounts();
    ensureBot();
    ensureSaimonChatBot();
    ensureHoursBot();
    removeAiBot();
    await ensureVapid();
    await persist();

    console.log(`💾 Хранилище: ${pool ? 'база данных PostgreSQL' : 'файлы в ' + DIR}`);
    if (!pool) console.warn('⚠️ DATABASE_URL не задан: данные лежат во временных файлах и пропадут при перезапуске на бесплатном хостинге');
    else console.log('✅ Сессии бессрочные — живут пока пользователь не выйдет вручную');
    console.log(`👤 Пользователей: ${read(F.users).length}, база создана: ${meta.createdAt}`);
}

// При остановке сервера дописываем в базу всё, что не успело сохраниться
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function finalSave() {
    for (const k of Object.keys(mem)) if (mem[k] !== saved[k]) dirty.add(k);
    await Promise.race([persist(), sleep(8000)]);
}
for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, async () => { await finalSave(); process.exit(0); });
process.on('beforeExit', () => { if (pool && dirty.size) finalSave(); });
// ========== СТИКЕР-ПАКИ ==========

function readPacks() { try { return read(F.stickerPacks) || []; } catch { return []; } }
function writePacks(p) { write(F.stickerPacks, p); }

app.get('/api/stickerpacks', (req, res) => {
    const packs = readPacks();
    res.json(packs.map(p => ({
        id: p.id, name: p.name, ownerId: p.ownerId,
        stickers: p.stickers || [], addedBy: p.addedBy || []
    })));
});

app.post('/api/stickerpacks', async (req, res) => {
    const me = req.uid;
    const name = String(req.body.name || '').trim().slice(0, 40);
    if (!name) return res.status(400).json({ error: 'Укажите название пака' });
    const packs = readPacks();
    if (packs.filter(p => p.ownerId === me).length >= 20)
        return res.status(400).json({ error: 'Максимум 20 паков' });
    const pack = { id: crypto.randomUUID(), name, ownerId: me, stickers: [], addedBy: [me], createdAt: new Date().toISOString() };
    packs.push(pack);
    writePacks(packs); await persist();
    res.json({ success: true, pack });
});

app.patch('/api/stickerpacks/:packId', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const pack = packs.find(p => p.id === req.params.packId);
    if (!pack) return res.status(404).json({ error: 'Пак не найден' });
    if (pack.ownerId !== me) return res.status(403).json({ error: 'Нет доступа' });
    const name = String(req.body.name || '').trim().slice(0, 40);
    if (!name) return res.status(400).json({ error: 'Укажите название' });
    pack.name = name; writePacks(packs); await persist();
    res.json({ success: true, pack });
});

app.delete('/api/stickerpacks/:packId', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const idx = packs.findIndex(p => p.id === req.params.packId);
    if (idx === -1) return res.status(404).json({ error: 'Пак не найден' });
    if (packs[idx].ownerId !== me) return res.status(403).json({ error: 'Нет доступа' });
    packs.splice(idx, 1); writePacks(packs); await persist();
    res.json({ success: true });
});

app.post('/api/stickerpacks/:packId/stickers', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const pack = packs.find(p => p.id === req.params.packId);
    if (!pack) return res.status(404).json({ error: 'Пак не найден' });
    if (pack.ownerId !== me) return res.status(403).json({ error: 'Только владелец может добавлять стикеры' });
    if ((pack.stickers || []).length >= 120) return res.status(400).json({ error: 'Максимум 120 стикеров' });
    const url = String(req.body.url || '');
    if (!fileOk(url)) return res.status(400).json({ error: 'Некорректный файл' });
    const emoji = String(req.body.emoji || '⭐').slice(0, 2);
    const sticker = { id: crypto.randomUUID(), url, emoji, addedAt: new Date().toISOString() };
    pack.stickers = pack.stickers || [];
    pack.stickers.push(sticker);
    writePacks(packs); await persist();
    res.json({ success: true, sticker, stickers: pack.stickers });
});

app.delete('/api/stickerpacks/:packId/stickers/:stickerId', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const pack = packs.find(p => p.id === req.params.packId);
    if (!pack) return res.status(404).json({ error: 'Пак не найден' });
    if (pack.ownerId !== me) return res.status(403).json({ error: 'Только владелец может удалять стикеры' });
    const before = (pack.stickers || []).length;
    pack.stickers = (pack.stickers || []).filter(s => s.id !== req.params.stickerId);
    if (pack.stickers.length === before) return res.status(404).json({ error: 'Стикер не найден' });
    writePacks(packs); await persist();
    res.json({ success: true, stickers: pack.stickers });
});

app.post('/api/stickerpacks/:packId/add', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const pack = packs.find(p => p.id === req.params.packId);
    if (!pack) return res.status(404).json({ error: 'Пак не найден' });
    pack.addedBy = pack.addedBy || [];
    if (pack.addedBy.includes(me)) return res.json({ success: true, already: true });
    pack.addedBy.push(me);
    writePacks(packs); await persist();
    res.json({ success: true });
});

app.post('/api/stickerpacks/:packId/remove', async (req, res) => {
    const me = req.uid;
    const packs = readPacks();
    const pack = packs.find(p => p.id === req.params.packId);
    if (!pack) return res.status(404).json({ error: 'Пак не найден' });
    if (pack.ownerId === me) return res.status(400).json({ error: 'Владелец не может убрать свой пак' });
    pack.addedBy = (pack.addedBy || []).filter(id => id !== me);
    writePacks(packs); await persist();
    res.json({ success: true });
});

// ========== КОНЕЦ СТИКЕР-ПАКОВ ==========

// Render усыпляет бесплатный сервис через 15 минут без входящих запросов.
// Пока сервер работает, он сам обращается к своему адресу раз в 8 минут (выключить: KEEP_ALIVE=0).
function keepAlive() {
    const url = process.env.RENDER_EXTERNAL_URL; // Render задаёт её сам
    if (!url || process.env.KEEP_ALIVE === '0' || typeof fetch !== 'function') return;
    setInterval(() => fetch(url.replace(/\/$/, '') + '/api/health').catch(e => console.error('keep-alive:', e.message)), 8 * 60 * 1000);
    console.log('⏰ keep-alive включён:', url);
}

const PORT = process.env.PORT || 3000;
init()
    .then(() => server.listen(PORT, () => { console.log(`🚀 SAIMONGRAM запущен: http://localhost:${PORT}`); keepAlive(); }))
    .catch(e => { console.error('Не удалось запустить сервер:', e); process.exit(1); }); // без данных не стартуем, чтобы не затереть базу пустым состоянием
